// One side's reaction on a message; an empty emoji removes it.
func (q *Queries) SetReaction(ctx context.Context, arg SetReactionParams) ([]SetReactionRow, error) {
	rows, err := q.db.Query(ctx, setReaction,
		arg.Emoji,
		arg.Side,
		arg.WorkspaceID,
		arg.ID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SetReactionRow{}
	for rows.Next() {
		var i SetReactionRow
		if err := rows.Scan(
			&i.ConversationID,
			&i.TeamID,
			&i.AssigneeID,
			&i.ChannelType,
			&i.ChannelID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const touchAutomated = `-- name: TouchAutomated :one
UPDATE conversations
SET last_message_at        = GREATEST(last_message_at, $1::timestamptz),
    last_message_preview   = $2,
    last_message_direction = 'out',
    status                 = CASE WHEN $3::boolean AND status = 'closed' THEN 'pending' ELSE status END,
    closed_at              = CASE WHEN $3::boolean AND status = 'closed' THEN NULL ELSE closed_at END
WHERE workspace_id = $4 AND id = $5
RETURNING team_id, assignee_id, channel_type, channel_id
`

type TouchAutomatedParams struct {
	At          time.Time
	Preview     string
	ToPending   bool
	WorkspaceID uuid.UUID
	ID          uuid.UUID
}

type TouchAutomatedRow struct {
	TeamID      *uuid.UUID
	AssigneeID  *uuid.UUID
	ChannelType string
	ChannelID   uuid.UUID
}

// An automated reply shows in the list but answers nobody: a customer waiting
// for a person stays waiting.
func (q *Queries) TouchAutomated(ctx context.Context, arg TouchAutomatedParams) (TouchAutomatedRow, error) {
	row := q.db.QueryRow(ctx, touchAutomated,
		arg.At,
		arg.Preview,
		arg.ToPending,
		arg.WorkspaceID,
		arg.ID,
	)
	var i TouchAutomatedRow
	err := row.Scan(
		&i.TeamID,
		&i.AssigneeID,
		&i.ChannelType,
		&i.ChannelID,
	)
	return i, err
}
